{
}

Method.Source:
    /// <summary>
    /// 136646-Customber Bank validation for DD
    /// </summary>
    /// <returns>bol</returns>
    public boolean validateWrite() //1
    {
        boolean ret = next validateWrite();
        CustBankAccount CustBankAccountext= this.cursor();
        custTable custTablebuf;
        select firstonly custTablebuf where custTablebuf.AccountNum ==CustBankAccountext.CustAccount
            && custTablebuf.BankAccount == CustBankAccountext.AccountID && custTablebuf.PaymMode == METConstants::DD;
        if(custTablebuf)
        {
            if(!CustBankAccountext.AccountNum)
            {
                ret = false;
                checkFailed("@MET:METCustValidation4");
            }
            if(!CustBankAccountext.RegistrationNum)
            {
                ret = false;
                checkFailed("@MET:METCustValidation4");
            }

        }
        return ret;
    }
